"use client";
/* Can, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Can(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("can"); }, []);
  return React.createElement("piix-pal", { "pal": "can", ...piixAttrs(props) });
}

export default Can;
